-- DAASI-3811  Medallia Files - Add Luxury Experience Tag
-- WHAT DOES UAT HOLD? The three procedures in UAT, compared with the three procedure files I built. Reads only.
--
-- WHY. Part 1 of the side-by-side test answered FALSE three times: the procedure text in UAT is not, character
-- for character, the text of the files I hold (spacing aside). The side-by-side test ran my copies. These two
-- queries show what the difference is, and whether yesterday's result also stands for what is deployed.
--
-- Line numbers count from the first line of the procedure body, the way Snowflake's error messages do.
-- To find the same line in the .sql file, add 4 (hotel, complete) or 5 (prospect).
-- WHAT TO SEND BACK: both grids. They hold procedure code only, no guest data.


-- ===========================================================================================================
-- QUERY 1. One line per procedure.
-- ===========================================================================================================
--   LINES_IN_UAT, LINES_IN_MY_FILE   how long each version is
--   ODD_CHARACTERS                   0 = keyboard characters only. Any other number = something pasted in that is
--                                    not on a keyboard, such as a non-breaking space or a curly quote.
--   SAME_CODE                        TRUE = the SQL is the same once comments and spacing are set aside
--   IS_THE_OLD_CODE                  TRUE = UAT still holds the procedure as it was before this change
-- HOW TO READ IT
--   SAME_CODE is TRUE on all three  -> only comments or spacing differ. Yesterday's result stands for what is
--                                      deployed, and the PROD data preview can go ahead. QUERY 2 will list the
--                                      comment lines that differ.
--   any FALSE                       -> run QUERY 2 and send me both grids before any further test.
SELECT PROCEDURE_NAME,
       LAST_ALTERED,
       REGEXP_COUNT(PROCEDURE_DEFINITION, '\n') + 1 AS LINES_IN_UAT,
       DECODE(PROCEDURE_NAME,
              'MEDALLIA_V_CUSTOMER_INVITATION_HOTEL_PROC', 294,
              'MEDALLIA_V_CUSTOMER_INVITATION_COMPLETE_PROC', 443,
              'MEDALLIA_PROSPECT_INVITATION_FILE_PROC', 146) AS LINES_IN_MY_FILE,
       OCTET_LENGTH(PROCEDURE_DEFINITION) - LENGTH(PROCEDURE_DEFINITION) AS ODD_CHARACTERS,
       MD5(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REGEXP_REPLACE(PROCEDURE_DEFINITION, '--[^\n]*', ''), ' '), CHAR(9)), CHAR(10)), CHAR(13)), CHAR(160)), CHAR(8203)), CHAR(65279)), CHAR(8239)))
         = DECODE(PROCEDURE_NAME,
              'MEDALLIA_V_CUSTOMER_INVITATION_HOTEL_PROC', 'aeebed257b2d90ce54ce8882cbd6472e',
              'MEDALLIA_V_CUSTOMER_INVITATION_COMPLETE_PROC', 'cb52a2ea028663edc1ad654ac1dd9b25',
              'MEDALLIA_PROSPECT_INVITATION_FILE_PROC', 'f42505a6f72ca296dbb96d94b30e086a') AS SAME_CODE,
       MD5(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REGEXP_REPLACE(PROCEDURE_DEFINITION, '--[^\n]*', ''), ' '), CHAR(9)), CHAR(10)), CHAR(13)), CHAR(160)), CHAR(8203)), CHAR(65279)), CHAR(8239)))
         = DECODE(PROCEDURE_NAME,
              'MEDALLIA_V_CUSTOMER_INVITATION_HOTEL_PROC', '90d0f3988d0c366c055757affbe525bb',
              'MEDALLIA_V_CUSTOMER_INVITATION_COMPLETE_PROC', '8bfc7871321ae659174af99429dcaa1e',
              'MEDALLIA_PROSPECT_INVITATION_FILE_PROC', 'a64cafa32a63ced0ba13e5be513ef782') AS IS_THE_OLD_CODE
FROM SNOWFLAKE.ACCOUNT_USAGE.PROCEDURES
WHERE DELETED IS NULL
AND PROCEDURE_CATALOG = 'DAAS_UAT'
AND PROCEDURE_SCHEMA IN ('DAAS_COMMON', 'HPDB')
AND PROCEDURE_NAME IN ('MEDALLIA_V_CUSTOMER_INVITATION_HOTEL_PROC',
                       'MEDALLIA_V_CUSTOMER_INVITATION_COMPLETE_PROC',
                       'MEDALLIA_PROSPECT_INVITATION_FILE_PROC')
ORDER BY PROCEDURE_NAME;


-- ===========================================================================================================
-- QUERY 2. Every line that differs, with its text.
-- ===========================================================================================================
--   WHERE_IT_IS   "1 Only in UAT"      a line UAT has and my file does not
--                 "2 Only in my file"  a line my file has and UAT does not
--                 "3 In both"          the same line, but a different number of times
--   A changed line shows up twice: once as "Only in UAT" with UAT's wording, once as "Only in my file" with mine.
--   Spacing is ignored, so a line that was only re-indented is not listed. No rows back = no line differs.
WITH UAT_LINES AS (
    SELECT P.PROCEDURE_NAME,
           F.INDEX + 1 AS LINE_NO,
           TRIM(REPLACE(REPLACE(F.VALUE::VARCHAR, CHAR(13)), CHAR(9), '    ')) AS LINE_TEXT,
           LEFT(MD5(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(F.VALUE::VARCHAR, ' '), CHAR(9)), CHAR(10)), CHAR(13)), CHAR(160)), CHAR(8203)), CHAR(65279)), CHAR(8239))), 10) AS LINE_ID
    FROM SNOWFLAKE.ACCOUNT_USAGE.PROCEDURES P,
         LATERAL FLATTEN(INPUT => SPLIT(P.PROCEDURE_DEFINITION, CHAR(10))) F
    WHERE P.DELETED IS NULL
    AND P.PROCEDURE_CATALOG = 'DAAS_UAT'
    AND P.PROCEDURE_SCHEMA IN ('DAAS_COMMON', 'HPDB')
    AND P.PROCEDURE_NAME IN ('MEDALLIA_V_CUSTOMER_INVITATION_HOTEL_PROC',
                       'MEDALLIA_V_CUSTOMER_INVITATION_COMPLETE_PROC',
                       'MEDALLIA_PROSPECT_INVITATION_FILE_PROC')
),
MY_LINES AS (
