        ('MEDALLIA_PROSPECT_INVITATION_FILE_PROC', 113, '2834ba78ba', '        ,CASE WHEN FCT.SOURCE_SYSTEM_NM = ''HOTEL'' THEN LUX.LOYALTY ELSE NULL END AS LOYALTY'),
        ('MEDALLIA_PROSPECT_INVITATION_FILE_PROC', 115, '9bc42f3e25', '    FROM HPDB.PROSPECT_TRANSACTION_FACT FCT'),
        ('MEDALLIA_PROSPECT_INVITATION_FILE_PROC', 116, '383ca70478', '    INNER JOIN HPDB_VW.PROSPECT_CUST_DIM_FINAL_VW CUST'),
