        ('MEDALLIA_PROSPECT_INVITATION_FILE_PROC', 121, '156948632e', '    LEFT JOIN DAAS_CORE_HOTEL_VW.HOTEL_GUEST_RESERVATIONS_FACT_VW RESV'),
        ('MEDALLIA_PROSPECT_INVITATION_FILE_PROC', 122, 'd6229e3c6d', '        ON FCT.RESERVATION_ID = TO_VARCHAR(RESV.RESERVATION_ID)'),
