        ('MEDALLIA_PROSPECT_INVITATION_FILE_PROC', 131, 'f94c2123aa', '        -- DAASI-3811 Luxury Experience tag, one row per reservation.'),
        ('MEDALLIA_PROSPECT_INVITATION_FILE_PROC', 132, '1c57994b3e', '        -- LOYALTY is typed by hand in LMS, so only the approved codes listed below are passed to Medallia.'),
        ('MEDALLIA_PROSPECT_INVITATION_FILE_PROC', 133, '0e19e0fe3e', '        SELECT PROPERTY_CD, RESERVATION_ID, MAX(TRIM(LOYALTY)) AS LOYALTY'),
        ('MEDALLIA_PROSPECT_INVITATION_FILE_PROC', 134, '1f366abe44', '        FROM DAAS_CORE_HOTEL.LMS73_HOTEL_RESERVATIONS_FACT'),
        ('MEDALLIA_PROSPECT_INVITATION_FILE_PROC', 135, 'ff63437b51', '        WHERE DELETE_IND = ''N'''),
        ('MEDALLIA_PROSPECT_INVITATION_FILE_PROC', 136, 'a730713e33', '        AND TRIM(LOYALTY) IN (''LUX'')'),
        ('MEDALLIA_PROSPECT_INVITATION_FILE_PROC', 137, 'e957a3a30a', '        GROUP BY PROPERTY_CD, RESERVATION_ID'),
