        ('MEDALLIA_PROSPECT_INVITATION_FILE_PROC', 139, '87a121e56f', '        ON RESV.RESERVATION_ID = LUX.RESERVATION_ID'),
        ('MEDALLIA_PROSPECT_INVITATION_FILE_PROC', 140, 'af1d072920', '        AND RESV.PROPERTY_CD = LUX.PROPERTY_CD'),
        ('MEDALLIA_PROSPECT_INVITATION_FILE_PROC', 141, 'd3b2617b1f', '    WHERE FCT.TRANSACTION_DT = : RUNDATE;'),
        ('MEDALLIA_PROSPECT_INVITATION_FILE_PROC', 143, '7bee72eeed', 'RETURN ''SUCCESS'';'),
        ('MEDALLIA_PROSPECT_INVITATION_FILE_PROC', 145, '3450a92350', 'END;')
    ) AS V (PROCEDURE_NAME, LINE_NO, LINE_ID, LINE_TEXT)
),
U AS (
    SELECT PROCEDURE_NAME, LINE_ID, COUNT(*) AS TIMES, MIN(LINE_NO) AS FIRST_LINE, MIN(LINE_TEXT) AS LINE_TEXT
    FROM UAT_LINES
    WHERE LINE_ID <> 'd41d8cd98f'
    GROUP BY PROCEDURE_NAME, LINE_ID
),
M AS (
    SELECT PROCEDURE_NAME, LINE_ID, COUNT(*) AS TIMES, MIN(LINE_NO) AS FIRST_LINE, MIN(LINE_TEXT) AS LINE_TEXT
    FROM MY_LINES
    GROUP BY PROCEDURE_NAME, LINE_ID
)
SELECT COALESCE(U.PROCEDURE_NAME, M.PROCEDURE_NAME) AS PROCEDURE_NAME,
       CASE WHEN M.LINE_ID IS NULL THEN '1 Only in UAT'
            WHEN U.LINE_ID IS NULL THEN '2 Only in my file'
            ELSE '3 In both' END AS WHERE_IT_IS,
       U.FIRST_LINE AS UAT_LINE,
       M.FIRST_LINE AS MY_FILE_LINE,
       NVL(U.TIMES, 0) AS TIMES_IN_UAT,
       NVL(M.TIMES, 0) AS TIMES_IN_MY_FILE,
       COALESCE(U.LINE_TEXT, M.LINE_TEXT) AS LINE_TEXT
FROM U
FULL OUTER JOIN M
    ON U.PROCEDURE_NAME = M.PROCEDURE_NAME
    AND U.LINE_ID = M.LINE_ID
WHERE NVL(U.TIMES, 0) <> NVL(M.TIMES, 0)
ORDER BY 1, COALESCE(U.FIRST_LINE, M.FIRST_LINE), 2;
